// Simple dodge game
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 400;
  const height = canvas.height = canvas.clientHeight || 600;

  const player = { x: width / 2 - 15, y: height - 30, w: 30, h: 30, speed: 5 };
  const blocks = [];
  let lastSpawn = 0;
  let spawnInterval = 1500; // ms
  let lastTime = 0;
  let gameOver = false;
  let startTime = performance.now();

  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function spawnBlock() {
    const size = Math.random() * 30 + 20;
    const x = Math.random() * (width - size);
    const speed = 2 + Math.random() * 3 + (performance.now() - startTime) / 20000; // increase over time
    blocks.push({ x, y: -size, w: size, h: size, speed });
  }

  function update(dt) {
    // player movement
    if (keys['ArrowLeft']) player.x -= player.speed;
    if (keys['ArrowRight']) player.x += player.speed;
    // keep inside bounds
    player.x = Math.max(0, Math.min(width - player.w, player.x));

    // blocks
    for (let i = blocks.length - 1; i >= 0; i--) {
      const b = blocks[i];
      b.y += b.speed;
      // remove offscreen
      if (b.y > height) blocks.splice(i, 1);
    }

    // collision
    for (const b of blocks) {
      if (b.x < player.x + player.w &&
          b.x + b.w > player.x &&
          b.y < player.y + player.h &&
          b.y + b.h > player.y) {
        gameOver = true;
        break;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // player
    ctx.fillStyle = 'steelblue';
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // blocks
    ctx.fillStyle = 'crimson';
    for (const b of blocks) {
      ctx.fillRect(b.x, b.y, b.w, b.h);
    }
    // timer
    ctx.fillStyle = 'black';
    ctx.font = '16px sans-serif';
    const elapsed = ((performance.now() - startTime) / 1000).toFixed(1);
    ctx.fillText(`Time: ${elapsed}s`, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = 'white';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
      ctx.font = '18px sans-serif';
      ctx.fillText(`Survived: ${elapsed}s`, width / 2, height / 2 + 30);
    }
  }

  function loop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const dt = timestamp - lastTime;
    lastTime = timestamp;

    if (!gameOver) {
      if (timestamp - lastSpawn > spawnInterval) {
        spawnBlock();
        lastSpawn = timestamp;
        // gradually speed up spawns
        spawnInterval = Math.max(300, spawnInterval - 10);
      }
      update(dt);
    }
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
